//! `SECRET_KEY_BASE` (the app's, for its session cookie) and `REDIS_URL`
//! (Sidekiq's, for its jobs), with the server's limits from
//! `MAX_CONNECTIONS`, `IDLE_TIMEOUT`, `HEADER_TIMEOUT`, `BODY_TIMEOUT`,
//! `WRITE_TIMEOUT`, `MIN_RATE` and `MAX_BODY_BYTES` (see
//! `rustonrails::Limits`).

use rustonrails::Limits;
use rustonrails::server::{self, Config};

fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    blog::models::behaviors();
    let config = Config {
        address: std::env::var("BIND").unwrap_or_else(|_| "127.0.0.1:3000".into()),
        database_url: std::env::var("DATABASE_URL").map_err(|_| "DATABASE_URL is not set")?,
        workers: std::env::var("WORKERS")
            .ok()
            .and_then(|w| w.parse().ok())
            .unwrap_or(5),
        limits: Limits::from_env()?,
        secret_key_base: std::env::var("SECRET_KEY_BASE").ok(),
        redis_url: None,
    };
    let running = server::start(blog::routes::routes(), config)?;
    eprintln!("blog listening on {}", running.address);
    running.join();
    Ok(())
}
